-- Adaptive Harness V1 initial SQLite schema.
-- Design artifact: the daemon, migrations runner and connectors are NOT implemented.
-- Initialize each connection with PRAGMA foreign_keys=ON and busy_timeout=5000.
-- Set PRAGMA journal_mode=WAL outside the transactional migration.
-- Times are stored in UTC ISO-8601 text; IDs are opaque and generated by the application.

BEGIN IMMEDIATE;

CREATE TABLE IF NOT EXISTS schema_migrations (
    version INTEGER PRIMARY KEY,
    description TEXT NOT NULL,
    applied_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS projects (
    id TEXT PRIMARY KEY,
    display_name TEXT NOT NULL,
    collection_enabled INTEGER NOT NULL DEFAULT 1 CHECK (collection_enabled IN (0, 1)),
    external_inference_enabled INTEGER NOT NULL DEFAULT 0 CHECK (external_inference_enabled IN (0, 1)),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS project_roots (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    root_fingerprint TEXT NOT NULL UNIQUE,
    -- Canonical root path remains local-only metadata; never include it in events.
    local_root_path TEXT NOT NULL,
    verified_at TEXT NOT NULL,
    UNIQUE (project_id, local_root_path)
);

CREATE TABLE IF NOT EXISTS provider_instances (
    id TEXT PRIMARY KEY,
    provider TEXT NOT NULL CHECK (provider IN ('codex', 'opencode')),
    runtime_version TEXT,
    launcher TEXT NOT NULL CHECK (launcher IN ('cli', 't3', 'other', 'unknown')),
    profile_fingerprint TEXT NOT NULL,
    capabilities_json TEXT NOT NULL CHECK (json_valid(capabilities_json)),
    last_doctor_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_provider_instances_provider
    ON provider_instances(provider, profile_fingerprint);

CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    provider_instance_id TEXT NOT NULL REFERENCES provider_instances(id),
    project_id TEXT NOT NULL REFERENCES projects(id),
    native_session_id TEXT NOT NULL,
    parent_session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL,
    status TEXT NOT NULL DEFAULT 'running'
        CHECK (status IN ('running', 'completed', 'failed', 'cancelled', 'unknown')),
    started_at TEXT NOT NULL,
    finished_at TEXT,
    UNIQUE (provider_instance_id, native_session_id)
);
CREATE INDEX IF NOT EXISTS idx_sessions_project ON sessions(project_id, started_at);
CREATE INDEX IF NOT EXISTS idx_sessions_parent ON sessions(parent_session_id);

CREATE TABLE IF NOT EXISTS events (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    source_instance_id TEXT NOT NULL REFERENCES provider_instances(id),
    event_id TEXT NOT NULL,
    project_id TEXT NOT NULL REFERENCES projects(id),
    session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL,
    native_session_id TEXT NOT NULL,
    event_type TEXT NOT NULL CHECK (event_type IN (
        'session.started', 'session.ended',
        'turn.started', 'turn.ended',
        'tool.started', 'tool.completed',
        'subagent.started', 'subagent.ended',
        'message.corrected', 'provider.diagnostic'
    )),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    occurred_at TEXT NOT NULL,
    observed_at TEXT NOT NULL,
    received_at TEXT NOT NULL,
    outcome TEXT CHECK (outcome IN ('succeeded', 'failed', 'cancelled', 'blocked', 'unknown')),
    privacy_class TEXT NOT NULL CHECK (privacy_class IN ('metadata', 'redacted_excerpt')),
    payload_digest TEXT NOT NULL,
    -- This JSON contains only validated and redacted allowlisted metadata.
    sanitized_payload_json TEXT NOT NULL CHECK (json_valid(sanitized_payload_json)),
    UNIQUE (source_instance_id, event_id)
);
CREATE INDEX IF NOT EXISTS idx_events_project_time ON events(project_id, received_at);
CREATE INDEX IF NOT EXISTS idx_events_session_sequence ON events(native_session_id, sequence);
CREATE INDEX IF NOT EXISTS idx_events_type ON events(event_type, received_at);

CREATE TABLE IF NOT EXISTS processing_jobs (
    id TEXT PRIMARY KEY,
    idempotency_key TEXT NOT NULL UNIQUE,
    event_sequence INTEGER REFERENCES events(sequence) ON DELETE SET NULL,
    project_id TEXT NOT NULL REFERENCES projects(id),
    job_type TEXT NOT NULL CHECK (job_type IN (
        'classify', 'learn', 'evaluate', 'publish', 'reconcile', 'prune'
    )),
    status TEXT NOT NULL DEFAULT 'queued'
        CHECK (status IN ('queued', 'leased', 'succeeded', 'failed', 'dead')),
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts INTEGER NOT NULL DEFAULT 5 CHECK (max_attempts >= 1),
    available_at TEXT NOT NULL,
    lease_owner TEXT,
    lease_until TEXT,
    payload_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload_json)),
    last_error_code TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_jobs_dispatch
    ON processing_jobs(status, available_at, lease_until);
CREATE INDEX IF NOT EXISTS idx_jobs_project
    ON processing_jobs(project_id, status, available_at);

CREATE TABLE IF NOT EXISTS evidence (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id),
    event_sequence INTEGER REFERENCES events(sequence) ON DELETE SET NULL,
    evidence_kind TEXT NOT NULL CHECK (evidence_kind IN (
        'failure', 'success', 'correction', 'decision', 'diagnostic', 'test_result'
    )),
    content_digest TEXT NOT NULL,
    -- Default NULL: snippets require explicit policy and sanitization.
    sanitized_excerpt TEXT,
    classification TEXT NOT NULL DEFAULT 'metadata'
        CHECK (classification IN ('metadata', 'redacted_excerpt')),
    observed_at TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_evidence_project ON evidence(project_id, observed_at);

CREATE TABLE IF NOT EXISTS artifacts (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL CHECK (kind IN ('memory', 'skill', 'rule')),
    logical_key TEXT NOT NULL,
    scope TEXT NOT NULL CHECK (scope IN ('project', 'global')),
    project_id TEXT REFERENCES projects(id),
    created_at TEXT NOT NULL,
    CHECK (
        (scope = 'project' AND project_id IS NOT NULL)
        OR (scope = 'global' AND project_id IS NULL)
    )
);
-- Two partial indexes avoid SQLite UNIQUE(NULL) behavior on global records.
CREATE UNIQUE INDEX IF NOT EXISTS idx_artifact_project_key
    ON artifacts(project_id, kind, logical_key) WHERE scope = 'project';
CREATE UNIQUE INDEX IF NOT EXISTS idx_artifact_global_key
    ON artifacts(kind, logical_key) WHERE scope = 'global';

CREATE TABLE IF NOT EXISTS proposals (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id),
    target_artifact_id TEXT REFERENCES artifacts(id),
    proposed_scope TEXT NOT NULL CHECK (proposed_scope IN ('project', 'global')),
    kind TEXT NOT NULL CHECK (kind IN ('memory', 'skill', 'rule')),
    idempotency_key TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'evaluating', 'eligible', 'promoted', 'rejected', 'quarantined')),
    candidate_digest TEXT NOT NULL,
    staged_path TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_proposals_project_status
    ON proposals(project_id, status);

CREATE TABLE IF NOT EXISTS artifact_versions (
    id TEXT PRIMARY KEY,
    artifact_id TEXT NOT NULL REFERENCES artifacts(id),
    source_proposal_id TEXT REFERENCES proposals(id),
    version_number INTEGER NOT NULL CHECK (version_number >= 1),
    content_digest TEXT NOT NULL,
    storage_path TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('draft', 'published', 'retired')),
    created_at TEXT NOT NULL,
    UNIQUE (artifact_id, version_number)
);

CREATE TABLE IF NOT EXISTS evaluations (
    id TEXT PRIMARY KEY,
    proposal_id TEXT NOT NULL REFERENCES proposals(id),
    baseline_version_id TEXT REFERENCES artifact_versions(id),
    candidate_version_id TEXT REFERENCES artifact_versions(id),
    status TEXT NOT NULL CHECK (status IN (
        'pending', 'running', 'passed', 'failed', 'inconclusive'
    )),
    baseline_score REAL CHECK (baseline_score IS NULL OR (baseline_score >= 0 AND baseline_score <= 1)),
    candidate_score REAL CHECK (candidate_score IS NULL OR (candidate_score >= 0 AND candidate_score <= 1)),
    sample_count INTEGER NOT NULL DEFAULT 0 CHECK (sample_count >= 0),
    report_digest TEXT,
    report_path TEXT,
    evaluator_version TEXT,
    started_at TEXT,
    finished_at TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_evaluations_proposal ON evaluations(proposal_id, created_at);

CREATE TABLE IF NOT EXISTS releases (
    id TEXT PRIMARY KEY,
    artifact_id TEXT NOT NULL REFERENCES artifacts(id),
    artifact_version_id TEXT NOT NULL REFERENCES artifact_versions(id),
    previous_release_id TEXT REFERENCES releases(id),
    state TEXT NOT NULL CHECK (state IN ('staged', 'active', 'superseded', 'rolled_back', 'failed')),
    git_revision TEXT,
    published_at TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_releases_artifact ON releases(artifact_id, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_releases_one_active
    ON releases(artifact_id) WHERE state = 'active';

CREATE TABLE IF NOT EXISTS publication_targets (
    id TEXT PRIMARY KEY,
    release_id TEXT NOT NULL REFERENCES releases(id),
    provider TEXT NOT NULL CHECK (provider IN ('codex', 'opencode')),
    install_scope TEXT NOT NULL CHECK (install_scope IN ('user', 'project')),
    target_fingerprint TEXT NOT NULL,
    installed_digest TEXT,
    status TEXT NOT NULL CHECK (status IN ('planned', 'installed', 'drifted', 'failed', 'removed')),
    applied_at TEXT,
    UNIQUE (release_id, provider, target_fingerprint)
);

CREATE TABLE IF NOT EXISTS memories (
    id TEXT PRIMARY KEY,
    project_id TEXT REFERENCES projects(id),
    scope TEXT NOT NULL CHECK (scope IN ('project', 'global')),
    kind TEXT NOT NULL CHECK (kind IN ('fact', 'decision', 'lesson', 'procedure')),
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    confidence REAL NOT NULL CHECK (confidence >= 0 AND confidence <= 1),
    status TEXT NOT NULL DEFAULT 'candidate'
        CHECK (status IN ('candidate', 'published', 'archived')),
    artifact_version_id TEXT REFERENCES artifact_versions(id),
    valid_until TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CHECK (
        (scope = 'project' AND project_id IS NOT NULL)
        OR (scope = 'global' AND project_id IS NULL)
    )
);
CREATE INDEX IF NOT EXISTS idx_memories_scope_status
    ON memories(scope, project_id, status, valid_until);

CREATE TABLE IF NOT EXISTS memory_evidence (
    memory_id TEXT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,
    evidence_id TEXT NOT NULL REFERENCES evidence(id),
    PRIMARY KEY (memory_id, evidence_id)
);

-- External content index: query must additionally enforce scope and status.
CREATE VIRTUAL TABLE IF NOT EXISTS memory_fts USING fts5(
    title, content, content='memories', content_rowid='rowid', tokenize='unicode61'
);
CREATE TRIGGER IF NOT EXISTS memory_fts_ai AFTER INSERT ON memories BEGIN
    INSERT INTO memory_fts(rowid, title, content) VALUES (new.rowid, new.title, new.content);
END;
CREATE TRIGGER IF NOT EXISTS memory_fts_ad AFTER DELETE ON memories BEGIN
    INSERT INTO memory_fts(memory_fts, rowid, title, content)
    VALUES ('delete', old.rowid, old.title, old.content);
END;
CREATE TRIGGER IF NOT EXISTS memory_fts_au AFTER UPDATE ON memories BEGIN
    INSERT INTO memory_fts(memory_fts, rowid, title, content)
    VALUES ('delete', old.rowid, old.title, old.content);
    INSERT INTO memory_fts(rowid, title, content) VALUES (new.rowid, new.title, new.content);
END;

CREATE TABLE IF NOT EXISTS inference_usage (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id),
    job_id TEXT REFERENCES processing_jobs(id),
    backend TEXT NOT NULL,
    model_name TEXT NOT NULL,
    input_tokens INTEGER NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
    output_tokens INTEGER NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
    estimated_cost_microusd INTEGER NOT NULL DEFAULT 0 CHECK (estimated_cost_microusd >= 0),
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_usage_project ON inference_usage(project_id, created_at);

CREATE TABLE IF NOT EXISTS audit_log (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
    actor_type TEXT NOT NULL CHECK (actor_type IN ('daemon', 'connector', 'user', 'learner', 'evaluator', 'publisher')),
    action TEXT NOT NULL,
    subject_type TEXT NOT NULL,
    subject_id TEXT NOT NULL,
    metadata_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata_json)),
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_project ON audit_log(project_id, created_at);

INSERT OR IGNORE INTO schema_migrations (version, description, applied_at)
VALUES (1, 'Initial event, memory, learning, registry and audit schema', '2026-11-02T00:00:00Z');

COMMIT;

